/// <summary>
/// Send original xml button clicked
/// </summary>
public void clicked()
{
    next clicked();

    FormControl ctrl = this;
    FormRun formRun =  ctrl.formRun();        
    FormDataSource custInvoiceJour_ds = formRun.dataSource(formDataSourceStr(CustInvoiceJournal, CustInvoiceJour));

    CustVendInvoiceJour::sendXML(custInvoiceJour_ds, PrintCopyOriginal::Original);
    custInvoiceJour_ds.research(true);
}
